import { OperationNotFoundError } from './errors.js';
import models from './models/index.js';
export const eventsResource = {
    findAll: (options = {}, adapter) => {
        const validatedOptions = eventsFindAllOptionsSchema.parse(options);
        return adapter.get({ path: models.event.path, type: models.event.endpoint, ...validatedOptions });
    },
    find: (id, options = {}, adapter) => {
        const validatedOptions = eventsFindOptionsSchema.parse(options);
        return adapter.get({ path: `${models.event.path}/${id}`, type: models.event.endpoint, ...validatedOptions });
    },
    create: (json, options = {}, adapter) => {
        const validatedOptions = baseOptionsSchema.parse(options);
        if (!models.event.operations.create)
            throw new OperationNotFoundError('Event create operation not found');
        const validatedData = models.event.operations.create.schema.parse(json);
        return adapter.post({
            json: validatedData,
            path: models.event.path,
            type: models.event.endpoint,
            ...validatedOptions,
        });
    },
    update: (id, json, options = {}, adapter) => {
        const validatedOptions = baseOptionsSchema.parse(options);
        if (!models.event.operations.update)
            throw new OperationNotFoundError('Event update operation not found');
        const validatedData = models.event.operations.update.schema.parse(json);
        return adapter.put({
            json: validatedData,
            path: `${models.event.path}/${id}`,
            type: models.event.endpoint,
            ...validatedOptions,
        });
    },
};
